changeSet.sql:
ALTER TABLE comment
DROP CONSTRAINT fk_comment_teacher;

ALTER TABLE comment
    ADD CONSTRAINT fk_comment_teacher
        FOREIGN KEY (teacher_id) REFERENCES "user"(id)
            ON DELETE SET NULL;

-- Drop old table if it exists DROP TABLE IF EXISTS teacher CASCADE;
-- Create new user_role table CREATE TABLE user_role ( id BIGSERIAL PRIMARY KEY, role_id BIGINT NOT NULL, user_id BIGINT NOT NULL, course_id BIGINT NOT NULL, name TEXT, short_name TEXT,
CONSTRAINT fk_user_role_user FOREIGN KEY (user_id) REFERENCES "user"(id) ON DELETE CASCADE, CONSTRAINT fk_user_role_course FOREIGN KEY (course_id) REFERENCES "course"(id) ON DELETE SET NULL );
